runner_script.source:
from __future__ import annotations

import hashlib
import importlib.metadata
import io
import json
import os
import platform
import re
import subprocess
import sys
import time
import winreg
import zipfile
from datetime import datetime, timedelta, timezone
from pathlib import Path

import psutil

ROOT = Path(__file__).resolve().parents[2]
OUTPUT = Path(__file__).resolve().parent / "results"
PROBES = ROOT / "docs/investigations/quality-security-review-2026-10-06/probes"
LOCK = "image_downloader/storage/interprocess_lock.py"
JST = timezone(timedelta(hours=9))


def now():
    return datetime.now(JST).isoformat()


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def git(*args):
    return subprocess.check_output(["git", *args], cwd=ROOT).decode("utf-8").strip()


def source_hashes():
    return {
        str(path.relative_to(ROOT)).replace("\\", "/"): digest(path)
        for path in sorted((ROOT / "src").rglob("*"))
        if path.is_file() and "__pycache__" not in path.parts and ".egg-info" not in str(path)
    }


def environment():
    packages = {
        re.sub(r"[-_.]+", "-", distribution.metadata["Name"]).lower(): distribution.version
        for distribution in importlib.metadata.distributions()
    }
    requirements = Path.home() / "Downloads/requirements.txt"
    pins = {}
    unsupported = []
    for line in requirements.read_text(encoding="utf-8-sig").splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if "==" not in stripped:
            unsupported.append(stripped)
            continue
        name, version = stripped.split("==", 1)
        pins[re.sub(r"[-_.]+", "-", name).lower()] = version
    differences = {
        name: {"required": version, "installed": packages.get(name)}
        for name, version in pins.items()
        if packages.get(name) != version
    }
    with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows NT\CurrentVersion") as key:
        windows = {
            name: winreg.QueryValueEx(key, name)[0]
            for name in ("DisplayVersion", "CurrentBuildNumber", "UBR", "EditionID")
        }
    return {
        "python": sys.version,
        "executable": sys.executable,
        "architecture": platform.architecture(),
        "platform": platform.platform(),
        "windows_registry": windows,
        "requirements": str(requirements),
        "requirements_sha256": digest(requirements),
        "pins": pins,
        "pin_count": len(pins),
        "mismatches": differences,
        "unsupported_requirement_lines": unsupported,
        "additional_packages": {name: version for name, version in packages.items() if name not in pins},
        "installed_packages": packages,
        "guard64_loaded_in_runner": any("guard64.dll" in mapping.path.lower() for mapping in psutil.Process().memory_maps()),
        "protection_context": "No security product per prior user declaration; settings not changed by this investigation",
    }


def write_evidence():
    (OUTPUT / "evidence.json").write_text(json.dumps(evidence, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def stop_owned(process):
    try:
        children = psutil.Process(process.pid).children(recursive=True)
    except psutil.NoSuchProcess:
        children = []
    for child in children:
        try:
            child.terminate()
        except psutil.NoSuchProcess:
            pass
    process.terminate()
    process.wait(timeout=10)
    _, alive = psutil.wait_procs(children, timeout=5)
    for child in alive:
        try:
            child.kill()
        except psutil.NoSuchProcess:
            pass


def run(label, args, timeout):
    command = [sys.executable, *map(str, args)]
    log = OUTPUT / (label + ".log")
    row = {"label": label, "command": command, "started_at": now(), "timeout_seconds": timeout, "log": str(log)}
    evidence["runs"].append(row)
    write_evidence()
    print(json.dumps({"start": label, "at": now()}), flush=True)
    started = time.monotonic()
    with log.open("w", encoding="utf-8") as stream:
        process = subprocess.Popen(command, cwd=ROOT, stdout=stream, stderr=subprocess.STDOUT, env=os.environ.copy())
        watchdog = False
        try:
            while process.poll() is None:
                try:
                    process.wait(timeout=15)
                except subprocess.TimeoutExpired:
                    elapsed = time.monotonic() - started
                    print(json.dumps({"running": label, "seconds": round(elapsed, 1)}), flush=True)
                    if elapsed > timeout:
                        watchdog = True
                        stop_owned(process)
                        break
        except BaseException:
            if process.poll() is None:
                stop_owned(process)
            raise
    row.update({"exitcode": process.returncode, "watchdog": watchdog, "seconds": time.monotonic() - started,
                "finished_at": now(), "log_sha256": digest(log), "output": log.read_text(encoding="utf-8")})
    write_evidence()
    print(json.dumps({"finished": label, "exitcode": row["exitcode"], "watchdog": watchdog,
                      "seconds": round(row["seconds"], 2)}), flush=True)
    return row


if __name__ == "__main__":
    os.chdir(ROOT)
    OUTPUT.mkdir(parents=True, exist_ok=False)
    evidence = {"started_at": now(), "execution": "native, outside Codex sandbox; all test phases sequential",
                "head": git("rev-parse", "HEAD"), "branch": git("branch", "--show-current"),
                "status_start": git("status", "--short"), "environment_start": environment(),
                "source_hashes_start": source_hashes(), "runs": [], "sources": {}}
    write_evidence()
    if evidence["environment_start"]["mismatches"] or evidence["environment_start"]["unsupported_requirement_lines"]:
        raise RuntimeError("Downloaded requirements did not match the installed environment")
    for label, ref in (("before", "c4ef652"), ("initialization", "3d40a0f"), ("final", evidence["head"])):
        destination = OUTPUT / "snapshots" / label
        destination.mkdir(parents=True, exist_ok=False)
        archive = subprocess.check_output(["git", "archive", "--format=zip", ref, "src"], cwd=ROOT)
        with zipfile.ZipFile(io.BytesIO(archive)) as bundle:
            for member in bundle.infolist():
                target = (destination / member.filename).resolve()
                if not target.is_relative_to(destination.resolve()):
                    raise RuntimeError("Unexpected archive path")
            bundle.extractall(destination)
        source = destination / "src"
        evidence["sources"][label] = {"commit": git("rev-parse", ref), "src": str(source),
                                      "lock_sha256": digest(source / LOCK),
                                      "lock_git_blob": git("rev-parse", ref + ":src/" + LOCK)}
    evidence["probes"] = {name: digest(PROBES / name) for name in ("history_lock_remediation.py", "history_lock_history_recheck.py")}
    write_evidence()
    os.environ["PYTHONDONTWRITEBYTECODE"] = "1"
    os.environ["COVERAGE_FILE"] = str(OUTPUT / ".coverage")
    run("lock-regression", ["-m", "pytest", "-q", "tests/v3/storage_output/test_interprocess_lock.py",
                            "-o", "faulthandler_timeout=45", "--junitxml=" + str(OUTPUT / "lock-regression.xml")], 300)
    run("v3-coverage", ["-m", "pytest", "tests/v3", "-q", "--cov=image_downloader", "--cov-report=term-missing",
                        "--cov-fail-under=75", "-o", "faulthandler_timeout=45",
                        "--junitxml=" + str(OUTPUT / "v3-coverage.xml"), "--durations=15"], 1500)
    run("remediation-comparison", [PROBES / "history_lock_remediation.py", OUTPUT / "comparison",
        "--source", "before=" + evidence["sources"]["before"]["src"],
        "--source", "initialization=" + evidence["sources"]["initialization"]["src"],
        "--source", "final=" + evidence["sources"]["final"]["src"],
        "--protection", "alternate-no-security-product-user-reported", "--repeats", "3",
        "--cold-rounds", "200", "--stable-rounds", "2000"], 2400)
    run("history-independent-20", [PROBES / "history_lock_history_recheck.py", OUTPUT / "history",
        "--source", "final=" + evidence["sources"]["final"]["src"],
        "--protection", "alternate-no-security-product-user-reported", "--repeats", "20"], 1200)
    evidence.update({"finished_at": now(), "head_after": git("rev-parse", "HEAD"),
                     "status_after": git("status", "--short"), "source_hashes_after": source_hashes(),
                     "environment_after": environment()})
    evidence["product_sources_unchanged"] = evidence["source_hashes_start"] == evidence["source_hashes_after"]
    write_evidence()
    print(json.dumps({"complete": True, "product_sources_unchanged": evidence["product_sources_unchanged"],
                      "exitcodes": {row["label"]: row["exitcode"] for row in evidence["runs"]}}), flush=True)
